import json
import pandas as pd


FIELD_MAP = {
    "user_id": {"user_id", "id", "userId"},
    "email": {"email", "email_address"},
    "name": {"full_name", "name", "userName"},
    "created_date": {"registration_date", "created_at", "joined"},
}


def normalize(record: dict) -> dict:
    out = {}
    for unified, aliases in FIELD_MAP.items():
        for alias in aliases:
            if alias in record and record[alias] is not None:
                out[unified] = record[alias]
                break
    if "status" in record and record["status"] is not None:
        out["status"] = record["status"]
    return out


def to_date_str(value) -> str:
    if value is None:
        return None
    s = str(value)
    return pd.to_datetime(s).strftime("%Y-%m-%d")


def load_source_a():
    with open("/data/source_a/users.json") as f:
        rows = json.load(f)
    return [normalize(r) for r in rows]


def load_source_b():
    df = pd.read_csv("/data/source_b/users.csv")
    return [normalize(r) for r in df.to_dict(orient="records")]


def load_source_c():
    df = pd.read_parquet("/data/source_c/users.parquet")
    return [normalize(r) for r in df.to_dict(orient="records")]


def index_by_user(records):
    return {int(r["user_id"]): r for r in records}


def main():
    sources = {
        "source_a": index_by_user(load_source_a()),
        "source_b": index_by_user(load_source_b()),
        "source_c": index_by_user(load_source_c()),
    }
    priority = ["source_a", "source_b", "source_c"]
    conflict_fields = ["name", "email", "created_date"]

    all_user_ids = sorted({uid for src in sources.values() for uid in src})

    merged_rows = []
    conflicts = []

    for uid in all_user_ids:
        present = {s: sources[s][uid] for s in priority if uid in sources[s]}

        merged = {"user_id": uid}
        for field in conflict_fields + ["status"]:
            for s in priority:
                if field in present.get(s, {}) and present[s][field] is not None:
                    merged[field] = present[s][field]
                    break

        for field in conflict_fields:
            values_by_source = {}
            for s in priority:
                if field in present.get(s, {}):
                    v = present[s][field]
                    if field == "created_date":
                        v = to_date_str(v)
                    values_by_source[s] = v
            distinct = set(values_by_source.values())
            if len(values_by_source) > 1 and len(distinct) > 1:
                selected = values_by_source[next(s for s in priority if s in values_by_source)]
                conflicts.append({
                    "user_id": uid,
                    "field": field,
                    "values": values_by_source,
                    "selected": selected,
                })

        if "created_date" in merged:
            merged["created_date"] = to_date_str(merged["created_date"])

        merged_rows.append(merged)

    out_df = pd.DataFrame(merged_rows, columns=["user_id", "name", "email", "created_date", "status"])
    out_df["user_id"] = out_df["user_id"].astype("int64")
    for col in ["name", "email", "created_date", "status"]:
        out_df[col] = out_df[col].astype("object")
    out_df.to_parquet("/app/merged_users.parquet", index=False)

    report = {"total_conflicts": len(conflicts), "conflicts": conflicts}
    with open("/app/conflicts.json", "w") as f:
        json.dump(report, f, indent=2)

    print(out_df)
    print(json.dumps(report, indent=2))


if __name__ == "__main__":
    main()

